CREATE SCHEMA IF NOT EXISTS collaboration_private;
REVOKE ALL ON SCHEMA collaboration_private FROM PUBLIC,anon;
GRANT USAGE ON SCHEMA collaboration_private TO authenticated,service_role;
ALTER FUNCTION public.invite_workspace_member(uuid,text,text,text) SET SCHEMA collaboration_private;
ALTER FUNCTION public.revoke_workspace_invitation(uuid) SET SCHEMA collaboration_private;
ALTER FUNCTION public.accept_workspace_invitation(text) SET SCHEMA collaboration_private;
ALTER FUNCTION public.reserve_attachment(uuid,uuid,text,text,bigint) SET SCHEMA collaboration_private;
ALTER FUNCTION public.finish_attachment(uuid) SET SCHEMA collaboration_private;
ALTER FUNCTION public.remove_attachment(uuid,boolean) SET SCHEMA collaboration_private;
ALTER FUNCTION public.mark_notifications(uuid,boolean) SET SCHEMA collaboration_private;
CREATE FUNCTION public.invite_workspace_member(p_workspace uuid,p_email text,p_role text,p_message text DEFAULT '') RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT collaboration_private.invite_workspace_member(p_workspace,p_email,p_role,p_message) $$;
CREATE FUNCTION public.revoke_workspace_invitation(p_id uuid) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT collaboration_private.revoke_workspace_invitation(p_id) $$;
CREATE FUNCTION public.accept_workspace_invitation(p_token text) RETURNS uuid LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT collaboration_private.accept_workspace_invitation(p_token) $$;
CREATE FUNCTION public.reserve_attachment(p_project uuid,p_task uuid,p_name text,p_mime text,p_size bigint) RETURNS public.attachments LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT collaboration_private.reserve_attachment(p_project,p_task,p_name,p_mime,p_size) $$;
CREATE FUNCTION public.finish_attachment(p_id uuid) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT collaboration_private.finish_attachment(p_id) $$;
CREATE FUNCTION public.remove_attachment(p_id uuid,p_finish boolean DEFAULT false) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT collaboration_private.remove_attachment(p_id,p_finish) $$;
CREATE FUNCTION public.mark_notifications(p_id uuid DEFAULT NULL,p_read boolean DEFAULT true) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT collaboration_private.mark_notifications(p_id,p_read) $$;
REVOKE ALL ON FUNCTION public.invite_workspace_member(uuid,text,text,text),public.revoke_workspace_invitation(uuid),public.accept_workspace_invitation(text),public.reserve_attachment(uuid,uuid,text,text,bigint),public.finish_attachment(uuid),public.remove_attachment(uuid,boolean),public.mark_notifications(uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.invite_workspace_member(uuid,text,text,text),public.revoke_workspace_invitation(uuid),public.accept_workspace_invitation(text),public.reserve_attachment(uuid,uuid,text,text,bigint),public.finish_attachment(uuid),public.remove_attachment(uuid,boolean),public.mark_notifications(uuid,boolean) TO authenticated;
CREATE POLICY outbox_server_only ON public.notification_outbox FOR ALL TO service_role USING(true) WITH CHECK(true);